const express = require('express');
const { exec, execFile } = require('child_process');
const app = express();

// --- VULNERABLE ENDPOINT ---
// Invokes a shell interpreter (/bin/sh) and concatenates raw input
app.get('/api/ping-unsafe', (req, res) => {
  const host = req.query.host;
  // Attacker input: '8.8.8.8; cat /etc/passwd' or '8.8.8.8 && rm -rf /'
  exec(`ping -c 1 ${host}`, (err, stdout, stderr) => {
    res.send(stdout);
  });
});

// --- SECURE REFACTORED IMPLEMENTATION ---
// Avoids shell execution entirely by invoking the binary directly with isolated argument arrays
app.get('/api/ping-safe', (req, res) => {
  const host = req.query.host;

  // Whitelist validate IP format before execution
  const ipRegex = /^[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}$/;
  if (!ipRegex.test(host)) {
    return res.status(400).send('Invalid IP address format');
  }

  // execFile does NOT spawn a shell; shell metacharacters (; & |) lose their special meaning
  execFile('/sbin/ping', ['-c', '1', host], (err, stdout) => {
    if (err) return res.status(500).send('Ping failed');
    res.send(stdout);
  });
});

const express = require('express');
const app = express();
app.use(express.json()); // Parses JSON bodies

// --- VULNERABLE ROUTE ---
// Attacker sends: { "username": "admin", "password": { "$ne": null } }
app.post('/api/login-unsafe', async (req, res) => {
  const { username, password } = req.body;
  // MongoDB evaluates: db.users.find({ username: 'admin', password: { $ne: null } })
  // Matches the admin user because password != null is true, logging in without password!
  const user = await db.collection('users').findOne({ username, password });
  if (user) return res.json({ token: 'jwt_admin_token' });
  res.status(401).send('Invalid');
});

// --- SECURE REFACTORED ROUTE ---
app.post('/api/login-safe', async (req, res) => {
  let { username, password } = req.body;

  // Ensure inputs are strictly strings; reject nested objects/operators
  if (typeof username !== 'string' || typeof password !== 'string') {
    return res.status(400).send('Credentials must be plain strings');
  }

  // Query now binds values strictly as string literals
  const user = await db.collection('users').findOne({ username: String(username) });
  if (!user || !(await verifyHash(password, user.passwordHash))) {
    return res.status(401).send('Invalid credentials');
  }
  res.json({ token: 'jwt_admin_token' });
});

