// 1. INSECURE SQL CONCATENATION (VULNERABLE)
async function getUserUnsafe(userEmail) {
  // Attacker input: admin@site.com' OR '1'='1
  const query = `SELECT id, name, email FROM users WHERE email = '${userEmail}'`;
  const result = await client.query(query);
  return result.rows;
}

// 2. SECURE PARAMETERIZED QUERY (PREPARED STATEMENT)
async function getUserSafe(userEmail) {
  // Placeholders ($1, $2) separate the SQL structure from the data
  const queryText = 'SELECT id, name, email FROM users WHERE email = $1';
  const values = [userEmail];

  // The database engine compiles query structure FIRST, then binds user data strictly as literal values
  const result = await client.query(queryText, values);
  return result.rows;
}

-- DANGEROUS STORED PROCEDURE (Vulnerable to SQL Injection)
-- Simply wrapping logic in a stored procedure does NOT protect against dynamic SQL concatenation!
CREATE OR REPLACE PROCEDURE find_user_unsafe(p_username TEXT)
LANGUAGE plpgsql AS $$
BEGIN
    -- Insecure: dynamically concatenates input into EXECUTE statement
    EXECUTE 'SELECT * FROM accounts WHERE username = ''' || p_username || '''';
END;
$$;

-- SECURE REFACTORED STORED PROCEDURE (Parameterized execution)
CREATE OR REPLACE PROCEDURE find_user_safe(p_username TEXT)
LANGUAGE plpgsql AS $$
BEGIN
    -- Secure: Uses standard static parameter binding
    EXECUTE 'SELECT * FROM accounts WHERE username = $1' USING p_username;
END;
$$;

